const FilterAndMitigateBlockers = (args) => {
  const [mitigated, setMitigated] = useState<string[]>(args.mitigatedBlockers);
  return (
    <BlockersView
      onNotify={fn()}
      mitigatedBlockers={mitigated}
      onToggleMitigated={(id) => {
        setMitigated((prev) =>
          prev.includes(id) ? prev.filter((item) => item !== id) : [...prev, id]
        );
        args.onToggleMitigated(id);
      }}
    />
  );
};

const SearchFilterAndSwitchToLinter = (args) => {
  const [migrated, setMigrated] = useState<string[]>(args.migratedComponents);
  return (
    <ComponentMatrixView
      enforceNoInlineStyle onNotify={fn()}
      migratedComponents={migrated}
      onToggleMigrated={(id) => {
        setMigrated((prev) =>
          prev.includes(id) ? prev.filter((item) => item !== id) : [...prev, id]
        );
        args.onToggleMigrated(id);
      }}
      onBulkToggleCategory={(ids, markDone) => {
        setMigrated((prev) => {
          const set = new Set(prev);
          for (const id of ids) {
            if (markDone) set.add(id);
            else set.delete(id);
          }
          return Array.from(set);
        });
        args.onBulkToggleCategory(ids, markDone);
      }}
    />
  );
};

const DynamicVarsAuditPanel = (args) => {
  const [migrated, setMigrated] = useState(args.isMigrated);
  return (
    <div className="max-w-md">
      <ComponentDetailPanel
        component={COMPONENT_AUDIT_INVENTORY.find((c) => c.id === 'select') ?? COMPONENT_AUDIT_INVENTORY[0]} enforceNoInlineStyle
        isMigrated={migrated}
        onToggleMigrated={(id) => {
          setMigrated((prev) => !prev);
          args.onToggleMigrated(id);
        }}
      />
    </div>
  );
};

