const InteractiveToggle = (args) => {
  const [checked, setChecked] = useState(args.checked);
  return (
    <div className="max-w-lg border border-[#222B36] bg-[#11161D]">
      <ScopeToggleRow
        id="story-toggle-lint" label="Strict Zero-Inline-Style Lint Gate" description={'Ban style={...} via Oxlint/ESLint + Omit<..., "style">; data-* attrs or JSX wrappers only.'}
        checked={checked}
        impactLabel={checked ? 'Enforced' : 'Off'}
        onToggle={() => {
          setChecked((prev) => !prev);
          args.onToggle();
        }}
      />
    </div>
  );
};
